10	/// <summary>
11	/// 從台大課程網抓取系所中英文名稱並寫入 Departments。
12	/// </summary>
13	public class DepartmentSync : IDepartmentSync
14	{
15	    private const int MaxDeptCodeLength = 8;
16	    private const int MaxNameLength = 512;
17	    private const int MaxShortNameLength = 128;
18	
19	    private readonly ILogger<DepartmentSync> _logger;
20	    private readonly IDbContextFactory<AppDbContext> _dbFactory;
21	    private readonly IHttpClientFactory _httpClientFactory;
22	    private readonly string _deptsUrl;
23	
24	    public DepartmentSync(
25	        ILogger<DepartmentSync> logger,
26	        IDbContextFactory<AppDbContext> dbFactory,
27	        IHttpClientFactory httpClientFactory,
28	        IOptions<NtuCourseApiOptions> options)
29	    {
30	        _logger = logger;
31	        _dbFactory = dbFactory;
32	        _httpClientFactory = httpClientFactory;
33	
34	        var opts = options.Value;
35	        var baseUrl = string.IsNullOrWhiteSpace(opts.DeptsBaseUrl) ? opts.BaseUrl : opts.DeptsBaseUrl;
36	        var path = string.IsNullOrWhiteSpace(opts.DeptsPath) ? "api/v1/depts" : opts.DeptsPath;
37	        _deptsUrl = $"{baseUrl.TrimEnd('/')}/{path.TrimStart('/')}";
38	    }
39	
40	    public async Task ExecuteAsync()
41	    {
42	        _logger.LogInformation("開始同步台大系所中英文名稱...");
43	        try
44	        {
45	            using var httpClient = _httpClientFactory.CreateClient("NTUCourseApi");
46	            var zhItems = await FetchDepartmentsAsync(httpClient, "zh_TW");
47	            var enItems = await FetchDepartmentsAsync(httpClient, "en_US");
48	
49	            if (zhItems.Count == 0 && enItems.Count == 0)
50	            {
51	                _logger.LogWarning("台大系所 API 未回傳任何資料，略過寫入。");
52	                return;
53	            }
54	
55	            var merged = MergeById(zhItems, enItems);
56	            await UpsertAsync(merged);
57	            _logger.LogInformation("台大系所同步完成，共 {Count} 筆。", merged.Count);
58	        }
59	        catch (Exception ex)
60	        {
61	            _logger.LogError(ex, "同步台大系所過程中發生未預期的錯誤");
62	            throw;
63	        }
64	    }
65	
66	    private async Task<List<NtuDeptItem>> FetchDepartmentsAsync(HttpClient httpClient, string lang)
67	    {
68	        var url = $"{_deptsUrl}?lang={Uri.EscapeDataString(lang)}";
69	        _logger.LogInformation("正在抓取系所列表: {Url}", url);
70	
71	        var response = await httpClient.GetAsync(url);
72	        if (!response.IsSuccessStatusCode)
73	        {
74	            _logger.LogWarning("系所 API 失敗 lang={Lang} status={Status}", lang, (int)response.StatusCode);
75	            return [];
76	        }
77	
78	        var result = await response.Content.ReadFromJsonAsync<NtuDeptsResponse>();
79	        var items = result?.Departments ?? [];
80	        _logger.LogInformation("系所 API lang={Lang} 回傳 {Count} 筆。", lang, items.Count);
81	        return items;
82	    }
83	
84	    private static Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)> MergeById(
85	        List<NtuDeptItem> zhItems,
86	        List<NtuDeptItem> enItems)
87	    {
88	        var merged = new Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)>(StringComparer.Ordinal);
89	
90	        foreach (var item in zhItems)
91	        {
92	            var id = item.Id?.Trim();
93	            if (string.IsNullOrEmpty(id)) continue;
94	            merged[id] = (item, null);
95	        }
96	
97	        foreach (var item in enItems)
98	        {
99	            var id = item.Id?.Trim();
100	            if (string.IsNullOrEmpty(id)) continue;
101	            if (merged.TryGetValue(id, out var existing))
102	                merged[id] = (existing.Zh, item);
103	            else
104	                merged[id] = (null, item);
105	        }
106	
107	        return merged;
108	    }
109	
110	    private async Task UpsertAsync(Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)> merged)
111	    {
112	        await using var db = await _dbFactory.CreateDbContextAsync();
113	        var existing = await db.Departments.ToDictionaryAsync(d => d.DeptCode, StringComparer.Ordinal);
114	        var now = DateTime.UtcNow;
115	
116	        foreach (var (id, pair) in merged)
117	        {
118	            var deptCode = Truncate(id, MaxDeptCodeLength);
119	            var nameZh = Truncate(FirstNonEmpty(pair.Zh?.Name, pair.En?.Name), MaxNameLength);
120	            var nameEn = Truncate(FirstNonEmpty(pair.En?.Name, pair.Zh?.Name), MaxNameLength);
121	            if (string.IsNullOrEmpty(nameZh) && string.IsNullOrEmpty(nameEn))
122	                continue;
123	
124	            var shortZh = TruncateNullable(Normalize(pair.Zh?.ShortName), MaxShortNameLength);
125	            var shortEn = TruncateNullable(Normalize(pair.En?.ShortName), MaxShortNameLength);
126	
127	            if (!existing.TryGetValue(deptCode, out var row))
128	            {
129	                row = new Department
130	                {
131	                    DeptCode = deptCode,
132	                    CreatedAt = now,
133	                };
134	                db.Departments.Add(row);
135	                existing[deptCode] = row;
136	            }
137	
138	            row.NameZh = nameZh;
139	            row.NameEn = nameEn;
140	            row.ShortNameZh = shortZh;
141	            row.ShortNameEn = shortEn;
142	            row.UpdatedAt = now;
143	        }
144	
145	        await db.SaveChangesAsync();
146	    }
147	
148	    private static string FirstNonEmpty(string? primary, string? fallback)
149	    {
150	        if (!string.IsNullOrWhiteSpace(primary)) return primary.Trim();
151	        if (!string.IsNullOrWhiteSpace(fallback)) return fallback.Trim();
152	        return string.Empty;
153	    }
154	
155	    private static string? Normalize(string? value) =>
156	        string.IsNullOrWhiteSpace(value) ? null : value.Trim();
157	
158	    private static string Truncate(string value, int max) =>
159	        value.Length <= max ? value : value[..max];
160	
161	    private static string? TruncateNullable(string? value, int max) =>
162	        value is null ? null : Truncate(value, max);
163	
164	    private class NtuDeptsResponse
165	    {
166	        [JsonPropertyName("departments")]
167	        public List<NtuDeptItem> Departments { get; set; } = [];
168	    }
169	
170	    private class NtuDeptItem
171	    {
172	        [JsonPropertyName("id")]
173	        public string? Id { get; set; }
174	
175	        [JsonPropertyName("name")]
176	        public string? Name { get; set; }
177	
178	        [JsonPropertyName("shortName")]
179	        public string? ShortName { get; set; }
180	    }
181	}
